import{_ as n,l as s,o as e,c as o,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Kata Containers","description":"","frontmatter":{"title":"Kata Containers","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kata-containers.md","filePath":"cs/kata-containers.md","lastUpdated":1789023840000}'),h={name:"cs/kata-containers.md"};function u(m,a,f,_,k,M){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="kata-containers" tabindex="-1">Kata Containers <a class="header-anchor" href="#kata-containers" aria-label="Permalink to &quot;Kata Containers&quot;">​</a></h1><div class="epigraph"><p>Kata 实现 OCI 运行时：每个容器（或 pod）一台 VM，里面再跑常规 Linux，接口仍是 create/start，隔离强度靠近 VM。</p><footer>—— 据 Kata 文档；[runc](/cs/container-runtime) 与 [Firecracker](/cs/firecracker-microvm)/QEMU 为后端</footer></div><p><a href="/cs/firecracker-microvm">Firecracker</a> 是 VMM。<a href="/cs/container-runtime">containerd</a> 要 <strong>runtime 插件</strong>。缺口是 Kata：用 VM 冒充容器接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>shim → Kata → QEMU 或 FC → 客户里的 kata-agent 起用户进程。缺口：镜像如何进 VM（block 或 virtio-fs）；网络 <a href="/cs/netns-veth">veth</a> vs 客户网卡。本课不把 k8s RuntimeClass 写成编排课。</p><p><span class="marginnote">pod 级 VM 摊启动成本。对象是接口兼容 + 内核隔离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>containerd 调 Kata 而非 runc。对照 gVisor 也是 runtime 替换。对照 <a href="/cs/nested-virtualization">nested</a>：Kata 在裸金属最甜。对照 overlay：层可在宿主做成块设备给客户。</p>',8)),(e(),l(p,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OCI%5B%22OCI%20create%22%5D%20--%3E%20KATA%5B%22Kata%20runtime%22%5D%0A%20%20KATA%20--%3E%20VMM%5B%22QEMU%20%E6%88%96%20Firecracker%22%5D%0A%20%20VMM%20--%3E%20AGENT%5B%22%E5%AE%A2%E6%88%B7%E5%86%85%20agent%20%E8%B5%B7%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Kata 让编排系统不改 API 就换隔离模型：失败时仍是「容器」，底层是 VM。税是内存与启动。不要写成安全认证。与 <a href="/cs/lsm-selinux">LSM</a>：宿主管 VMM，客户另有策略。</p><p>文件系统语义（fsync、mmap）依赖 virtio-fs/9p 的实现裂缝。</p><p>实现上：virtio-fs 或块设备把镜像送进 VM，语义与宿主 overlay 不完全一样。pod 级 VM 让 pause 容器和业务容器共享一台客户机。RuntimeClass 才切换 runc/kata。 读法上只引用<a href="/cs/firecracker-microvm">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Kata Containers</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 hypervisor 插件。不保证 Windows。下一课更极端：unikernel。</p><p>版本字段会变，课序钉的是机制对象「Kata Containers」，不是某一主线内核的结构体名。 后课默认：OCI 可由 VM 实现。把应用与内核链成单一映像，下一课 unikernel。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kata：OCI 表面，VM 隔离。</li><li>客户内 agent 才 exec 用户。</li><li>unikernel 是下一课。</li><li>出处：Kata 文档；OCI；KVM。</li></ul>',11))])}const v=n(h,[["render",u]]);export{C as __pageData,v as default};
